def sq(x) { return x * x }
def big(x) { return x > 1 }
def add(a, b) { return a + b }
print(map(sq, [1, 2, 3]), map(str, [1, 2]), map(len, ["a", "bb"]), map(sq, []), map(upper, ["a"]), map(abs, [-1, 2]))
print(filter(big, [1, 2, 3]), filter(big, []), filter(big, [0, 1]))
print(reduce(add, [1, 2, 3]), reduce(add, [1, 2, 3], 10), reduce(add, [], 5), reduce(add, [7]), reduce(max, [1, 5, 2]), reduce(add, ["a", "b", "c"]))

def sub(a, b) { return a - b }
def cat(a, b) { return "(" + a + b + ")" }
print(reduce(sub, [10, 1, 2]), reduce(sub, [10, 1, 2], 100), reduce(cat, ["a", "b", "c"]), reduce(cat, ["b", "c"], "a"))

let calls = []
def f(x) { append(calls, x)
return x }
def keep(x) { append(calls, x * 10)
return x > 1 }
map(f, [3, 1, 2])
filter(keep, [1, 2])
print(calls)

def t2(f, a, b) { try { f(a, b) } catch e { print(e) } }
def add(a, b) { return a + b }
t2(map, 5, [1])
t2(map, len, 5)
t2(filter, "x", [1])
t2(filter, len, "x")
t2(reduce, add, 5)
t2(reduce, 5, [1])
