for i = 1 to 22 { big = big * 10 }
let tiny = 1.0
for i = 1 to 5 { tiny = tiny / 10 }
print(json.dumps(1.0), json.dumps(2.5), json.dumps(big), json.dumps(tiny), json.dumps(100.5), json.dumps(1000000.0), json.dumps(0.1 + 0.2), json.dumps(-0.5), json.dumps(0.0001))
