print(n, json.dumps(n))
print(json.loads("12345678901234567890"), json.loads("0.1") + json.loads("0.2"))

let v = {name: "Nova", n: [1, 2.5, true, 0], nested: {x: "é\n", y: 1}, none: json.loads("null")}
let text = json.dumps(v)
print(text)
print(json.loads(text) == v, json.loads(json.pretty(v)) == v)
print(json.dumps(json.loads(text)) == text)
